// src/components/Equipment.js
import React, { useState } from 'react';
import styled from 'styled-components';

const EquipmentGrid = styled.div`
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
  position: relative;
`;

const EquipmentItem = styled.div`
  border: 1px solid #ddd;
  border-radius: 8px;
  padding: 10px;
  background-color: #fff;
  text-align: center;
  position: relative;
  transition: transform 0.3s ease, box-shadow 0.3s ease;
  cursor: pointer;
  overflow: hidden;

  &:hover {
    box-shadow: 0 8px 16px rgba(0, 0, 0, 0.1);
  }

  ${({ expanded }) =>
    expanded &&
    `
      grid-column: span 4;
      transform: scale(1.05);
      z-index: 1;
    `}
`;

const EquipmentImage = styled.img`
  width: 100%;
  height: 200px;
  object-fit: cover;
  border-radius: 8px;
`;

const ExpandedSection = styled.div`
  margin-top: 10px;
  background-color: #f9f9f9;
  padding: 15px;
  border-radius: 5px;
  transition: max-height 0.3s ease, opacity 0.3s ease;
  max-height: ${({ expanded }) => (expanded ? '300px' : '0')};
  opacity: ${({ expanded }) => (expanded ? 1 : 0)};
  overflow: hidden;
`;

const Equipment = ({ equipment, handleSelect }) => {
  const [expandedItem, setExpandedItem] = useState(null);

  const toggleExpand = (item) => {
    setExpandedItem(expandedItem === item ? null : item);
  };

  const renderDetailsOrSpecs = (item) => {
    if (item.Tech_Specs) {
      return (
        <div>
          <h4>Tech Specs</h4>
          <ul>
            {Object.entries(item.Tech_Specs).map(([key, value]) => (
              <li key={key}>
                <strong>{key}:</strong> {value}
              </li>
            ))}
          </ul>
        </div>
      );
    } else if (item.Details) {
      return (
        <div>
          <h4>Details</h4>
          <ul>
            {item.Details.map((detail, index) => (
              <li key={index}>{detail}</li>
            ))}
          </ul>
        </div>
      );
    }
    return <p>No additional information available.</p>;
  };

  return (
    <EquipmentGrid>
      {equipment.map((item) => (
        <EquipmentItem
          key={item.id}
          expanded={expandedItem === item}
          onClick={() => toggleExpand(item)}
        >
          <EquipmentImage src={item.Image_URL} alt={item.Name} />
          <h3>{item.Name}</h3>
          <p>Brand: {item.Brand}</p>
          <p>Price: ${item.Price}</p>

          <ExpandedSection expanded={expandedItem === item}>
            {renderDetailsOrSpecs(item)}
            <a href={item.Link} target="_blank" rel="noopener noreferrer">
              View Product Page
            </a>
            <button onClick={() => handleSelect(item)} style={{ marginTop: '10px' }}>
              Select Item
            </button>
          </ExpandedSection>
        </EquipmentItem>
      ))}
    </EquipmentGrid>
  );
};

export default Equipment;
